const dstr = t => { const d = E.dateOf(Math.min(t, E.SLOTS-1)); return DAYS[d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + MON[d.getUTCMonth()]; };
const seas = y => y + '/' + String((y+1)%100).padStart(2,'0');
const C = i => S.C[i], cn = i => i < 0 ? 'Free agent' : esc(S.C[i].n);
