  h += '<main><div class="grid"><div class="tile c8"><h3>Select your club</h3><div class="row"><label>League<select id="ng-li" data-c="ngli">' + D.leagues.map((l,i) => '<option value="' + i + '"' + (i === g.li ? ' selected' : '') + '>' + esc(l.n) + '</option>').join('') + '</select></label><label>Find a club<input type="text" id="ng-q" data-i="ngq" value="' + esc(g.q) + '" placeholder="Type a name"></label></div>';
  h += '<div class="clubs" role="listbox">' + list.map(i => '<div class="c" role="option" tabindex="0" aria-selected="' + (i === g.club) + '" data-a="ngclub" data-v="' + i + '">' + crest(i, 46) + '<b>' + esc(D.clubs[i][0]) + '</b><small>' + (q ? esc(D.leagues[D.clubs[i][1]].n) + ' · ' : '') + clubStrength(i).toFixed(0) + ' rated</small></div>').join('') + '</div></div>';
  h += '<div class="hero c4" style="background:linear-gradient(160deg,color-mix(in srgb,var(--kit) 45%,var(--tile)),var(--tile) 70%)"><div class="row" style="align-items:center">' + crest(g.club, 84) + '<div><h2>' + esc(club[0]) + '</h2><p class="mu">' + esc(D.leagues[club[1]].n) + '</p></div></div><div class="kv"><div><small>Squad rating</small><b>' + clubStrength(g.club).toFixed(1) + '</b></div><div><small>Players</small><b>' + D.players.filter(p => p[4] === g.club).length + '</b></div></div>';
  h += '<label>Start in division<select id="ng-start" data-c="ngstart">' + tiers.map(i => '<option value="' + i + '"' + (i === g.start ? ' selected' : '') + '>' + esc(D.leagues[i].n) + (i === club[1] ? ' (real)' : '') + '</option>').join('') + '</select></label><p class="note">Leave this on the real division, or drop a giant down the pyramid (your club swaps places with one from that division).</p>' + ngOptions() + '<button class="pri" data-a="start" style="font-size:1.4rem;padding:14px">Start career</button><label>Or load a save file<input type="file" id="imp" accept=".json,application/json" data-c="import"></label><p class="note">Challenges are optional. Pick one up any time from the Objectives tab.</p></div></div></main>';
