  if (V.tab === 'central' && V.sub.central === 'news' && S.news.length) V.newsSeen = S.news[0].id;
  const newsN = S.news.filter(n => n.id > V.newsSeen).length;
  let h = '<div class="top"><div class="id">' + crest(S.user, 46) + '<div style="min-width:0"><div class="nm">' + esc(u.n) + '</div><div class="sub"><b>' + seas(S.season) + '</b> · ' + esc(L.n) + ' · <b>' + ord(userPos()) + '</b>' + (S.dc ? ' <span class="tag wn">Daily</span>' : S.opts.iron ? ' <span class="tag neg">Ironman</span>' : '') + '</div></div></div>';
  h += '<div class="chips"><div>Date<b>' + (S.dd > 0 ? 'Deadline day' : dfmt(E.dateNow())) + '</b></div><div>Transfer budget<b>' + M(u.bal - E.reserved()) + '</b></div><div>Wages<b>' + M(bill) + ' / ' + M(u.wb) + '</b></div><div>Window<b class="' + (open ? 'up' : 'mu') + '">' + (open ? 'Open' : 'Closed') + '</b></div></div>';
