  for (let r = 5; r >= 0; r--) { if (!rows[r].length) continue; h += '<div class="ln">' + rows[r].map(k => { const p = xi.pl[k]; return '<div class="sl ' + (p ? fitCls(p.fi) : 'lo') + '" tabindex="0" data-a="slot" data-v="' + k + '"><b>' + POS[xi.slots[k]] + ' · ' + (p ? Math.round(xi.r[k]) : '-') + (p && u.cap === p.id ? ' · C' : '') + '</b><span>' + (p ? esc(p.n) : 'Empty') + '</span>' + (p && (u.rl || {})[k] ? '<small>' + E.ROLEDEF[xi.slots[k]][u.rl[k]][0] + '</small>' : '') + (p ? '<span class="fb"><i style="width:' + Math.round(p.fi) + '%"></i></span><small>' + pct(p.fi) + ' fit' + (p.kn ? ' · just back' : p.sh < 55 ? ' · rusty' : '') + '</small>' : '') + '</div>'; }).join('') + '</div>'; }
  h += '</div><div class="kv"><div><small>Attack</small><b>' + xi.att.toFixed(1) + '</b></div><div><small>Defence</small><b>' + xi.def.toFixed(1) + '</b></div><div><small>XI average</small><b>' + xi.avg.toFixed(1) + '</b></div><div><small>Average fitness</small><b>' + pct(xi.pl.filter(Boolean).reduce((s,p) => s + p.fi, 0) / Math.max(1, xi.pl.filter(Boolean).length)) + '</b></div></div><p class="note">Select a position to choose who plays there. The bar under each name is match fitness: green is fresh, amber is tired (below 80%), red is exhausted (below 60%). The captain lifts morale after every match he starts.</p></div>';
  h += benchTile(xi);
  const all = u.sq.slice().sort((a,b) => a.p - b.p || b.o - a.o);
  h += '<div class="tile"><h3>Squad condition</h3><div class="tw"><table><thead><tr><th>Pos</th><th>Player</th><th class="n">OVR now</th><th class="n">Fitness</th><th class="n">Sharpness</th><th class="n">Form</th><th class="n">Morale</th><th>Status</th><th></th></tr></thead><tbody>' + all.map(p => '<tr class="clk" data-a="player" data-v="' + p.id + '"><td>' + posT(p.p) + '</td><td>' + (inXI.has(p.id) ? '<b>' + esc(p.n) + '</b>' : esc(p.n)) + '</td><td class="n">' + ovrCell(p) + '</td><td class="n">' + bar(p.fi) + ' ' + pct(p.fi) + '</td><td class="n">' + bar(p.sh) + ' ' + pct(p.sh) + '</td><td class="n">' + COL.fm[2](p) + '</td><td class="n">' + bar(p.mo) + '</td><td>' + status(p) + '</td><td>' + (inXI.has(p.id) ? '<span class="tag ok">Starting</span>' : bn.has(p.id) ? '<span class="tag">Bench</span>' : '') + '</td></tr>').join('') + '</tbody></table></div><p class="note">Fitness falls with every match and comes back between games. Sharpness is built by playing and fades when a player sits out. A tired player performs worse and is injured more easily; a player just back from injury is at higher risk for his first two weeks.</p></div></div>';
